<script>
import GIcon from './GIcon.vue'
export default{name:'GlacierCatalog',components:{GIcon},props:{materials:Array},emits:['location','detail','new','export'],data(){return{q:'',category:'全部物料'}},computed:{rows(){return this.materials.filter(m=>[m.mpn,m.name,m.location].join(' ').toLowerCase().includes(this.q.toLowerCase())&&(this.category==='全部物料'||m.category===this.category))},categories(){return['全部物料',...new Set(this.materials.map(m=>m.category))]}}};
</script>
<template><div><div class="g-page-heading"><div><span class="g-eyebrow">MATERIAL LIBRARY</span><h1>物料库<span class="g-title-dot">.</span></h1></div><div class="g-row"><button class="g-btn" @click="$emit('export')"><GIcon name="download" :size="18"/>导出</button><button class="g-btn dark" @click="$emit('new')"><GIcon name="plus" :size="18"/>新增物料</button></div></div><section class="g-card g-catalog"><div class="g-catalog-toolbar"><label class="g-input-search"><GIcon name="search" :size="18"/><input v-model="q" placeholder="搜索型号、名称或库位" aria-label="搜索物料"/></label><select v-model="category" aria-label="物料分类"><option v-for="c in categories" :key="c">{{c}}</option></select><span class="g-muted">{{rows.length}} 项结果</span></div><div class="g-table-scroll"><table class="g-table"><thead><tr><th>物料</th><th>分类／封装</th><th>可用</th><th>预留</th><th>库位</th><th>操作</th></tr></thead><tbody><tr v-for="m in rows" :key="m.id"><td><div class="g-material-cell"><span class="g-chip-icon"><GIcon name="chip" :size="24"/></span><span><b>{{m.mpn}}</b><small>{{m.name}}</small></span></div></td><td>{{m.category}}<small class="g-cell-sub">{{m.package}}</small></td><td class="g-quantity">{{m.available??'—'}}<small> {{m.unit}}</small></td><td>{{m.reserved??'—'}}</td><td><button class="g-location-link" @click="$emit('location',m)"><GIcon name="pin" :size="15"/>{{m.location}}</button></td><td><button class="g-text-btn" @click="$emit('detail',m)">详情 <GIcon name="arrow" :size="16"/></button></td></tr><tr v-if="!rows.length"><td colspan="6" class="g-empty-row">没有匹配的物料，换个关键词试试。</td></tr></tbody></table></div></section></div></template>